#!/usr/bin/env python3
"""Freeze arithmetic feasibility results; not a whole-core qualification."""
from pathlib import Path
import hashlib,json,re,shutil
ROOT=Path(__file__).resolve().parents[3];BASE=ROOT/'docs/measurements/os30-fps25-20261005/phase10';OUT=BASE/'fpu-feasibility';TOOLS=ROOT/'tools/experiments/os30_fps25_20261005'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
rtl=OUT/'rtl';rtl.mkdir()
for p,name in [(OUT/'generator/fma-rtl/GeometryFmaProbe.v','GeometryFmaProbe.v'),(TOOLS/'phase10_float_vertex.v','geometry_float_vertex.v'),(TOOLS/'phase10_float_recip.v','geometry_float_recip.v')]:shutil.copy2(p,rtl/name)
checks={k:json.loads((OUT/v).read_text()) for k,v in {'arithmetic':'sim-v2-result.json','random_float_vertices':'vertex-v2-result.json','native_vertices':'native-result.json','random_reciprocals':'recip-result.json','native_reciprocals':'native-recip-result.json'}.items()}
assert all(v['mismatches']==0 for v in checks.values())
fits={}
for key,folder in [('arithmetic','fit-v1'),('scalar_vertex','vertex-fit-v2'),('reciprocal','recip-fit-v1')]:
 d=OUT/folder/'output_files';s=(d/'probe.fit.summary').read_text();t=(d/'probe.sta.rpt').read_text();fits[key]={'alms':int(re.search(r'Logic utilization \(in ALMs\) : ([\d,]+)',s)[1].replace(',','')),'dsps':int(re.search(r'Total DSP Blocks : (\d+)',s)[1]),'memory_bits':int(re.search(r'Total block memory bits : ([\d,]+)',s)[1].replace(',','')),'worst_reported_fmax_mhz':min(float(x) for x in re.findall(r';\s+([0-9.]+) MHz\s+;\s+[0-9.]+ MHz\s+;\s+clk',t)),'scope':'Standalone saved-seed2 virtual-pin component fit. Not timing closure or fit proof inside os30.'}
files=[Path(__file__),*rtl.iterdir()]
files += [TOOLS/n for n in ['phase10_fpu_frontend.scala','phase10_fpu_probe.cpp','phase10_float_vertex.v','phase10_float_vertex.cpp','phase10_float_native.cpp','phase10_float_recip.v','phase10_float_recip.cpp','phase10_recip_native.cpp']]
for folder in ['fit-v1','vertex-fit-v2','recip-fit-v1']:
 d=OUT/folder;files += [d/'probe.qsf',d/'timing.sdc',d/'output_files/probe.fit.summary',d/'output_files/probe.fit.rpt',d/'output_files/probe.sta.rpt'];files+=list(d.glob('*.v'))
for n in ['sim-v2-result.json','vertex-v2-result.json','native-result.json','recip-result.json','native-recip-result.json','native-vectors.txt','native-reciprocal.txt','native-vector-inputs.json','generator/src/main/scala/vexiiriscv/execute/fpu/FpuAdd.scala','generator/src/main/scala/vexiiriscv/execute/fpu/Interface.scala','generator/src/main/scala/vexiiriscv/test/GeometryFmaProbe.scala']:
 files.append(OUT/n)
files += [BASE/'cpu-audit'/n for n in ['native-A-transform-vectors.json','native-A-reciprocal-vectors.json','native-A-states.bin']]
result={'passed_feasibility_gates':True,'deployable':False,'production_changed':False,'physical_fps_measured':False,'primitive_contract':'Normal/zero operands, RNE. FMA reproduces retained os30 product truncation to25 fractional bits before shared VexiiRiscv FpuAdd. Exceptional/subnormal inputs and nonnormal outputs raise unsupported. Shared adder code is reused directly.','checks':checks,'standalone_fits':fits,'rtl_sha256':{p.name:sha(p)for p in rtl.iterdir()},'evidence_sha256':{str(p.relative_to(ROOT)):sha(p)for p in files},'remaining':['Integrated raw-vertex DMA and matrix/material ownership.','Shared lighting, clipping, culling and fixed-point payload conversion.','Vertex-cache/rasterizer submission and full rendering equivalence.','Whole-os30 area/timing qualification and coupled performance measurements.','Controlled Pocket measurements after a substantial modeled gain.'],'notes':['Scalar vertex wrapper uses original float32 XYZ and exact disassembled F11 operation order. Earlier int16/source-order draft is archived as a rejected interface draft.','Scalar transform timing includes input to output control but excludes matrix upload.','Arithmetic tests use333-bit reference arithmetic to preserve tiny signed additions at reduced-FMA rounding ties; initial long-double oracle failed those cases.','The user goal is not met by isolated arithmetic feasibility results.']}
(OUT/'result.json').write_text(json.dumps(result,indent=2)+'\n')
(OUT/'REPORT.txt').write_text('''Float geometry arithmetic feasibility\n\nThe arithmetic building blocks fit comfortably as standalone components and\nmatch the retained CPU on the tested native vertex corpus. This is a feasible\nstarting point for a geometry frontend, not a completed accelerator or an FPS\nimprovement claim. No production source, package, clock or SD card changed.\n\nStandalone saved-seed 2 Cyclone V fits:\n  Multiply/FMA primitive: 424 ALMs, 1 DSP, 0 memory bits, 123.02 MHz worst Fmax.\n  Scalar float-vertex transform: 840 ALMs, 1 DSP, 0 memory bits, 117.91 MHz.\n  Reciprocal primitive: 129 ALMs, 0 DSP, 0 memory bits, 113.90 MHz.\nThe scalar transform includes the arithmetic primitive; do not sum those two\nrows. Isolated fits do not prove placement or timing inside the full os30 core.\n\nArithmetic and native validation:\n  181,641 supported multiply/FMA results match a 333-bit oracle.\n  2,974 exceptional or out-of-range arithmetic inputs were flagged.\n  16,384 components from 4,096 random float vertices match the same oracle.\n  All 920 XYZW values from 230 fresh actual-A CPU vertices match bit for bit.\n  246,156 reciprocal results and 3,844 unsupported classifications pass.\n  All 230 fresh actual-A CPU reciprocal results match bit for bit.\nThe native corpus comprises 20 sampled calls, not 200 native-replayed calls.\n\nThe original VexiiRiscv FpuAdd is reused directly. This preserves os30's existing\nreduced-accuracy FMA rule: its product is truncated to 25 fractional bits before\naddition. Normal and zero inputs use RNE; unsupported conditions are flagged.\nThe scalar transform consumes original float32 XYZ, not packed int16 vertices.\nIts operation order matches the disassembled F11 loader: Y multiply, X FMA,\ntranslation add, Z FMA, and the final X aspect multiply.\n\nThe scalar transform takes 53 cycles per vertex. Parent work batches vertices\nto fill the arithmetic pipeline; those results are recorded separately. The\nreciprocal takes 26 cycles normally and one cycle for powers of two. It has an\nindependent datapath and can overlap transform work.\n\nStill required: raw descriptor DMA, state ownership, lighting, clipping and\nculling, float-to-fixed conversion, raster submission, full image equivalence,\nwhole-core fitting/timing and coupled performance. User-visible FPS remains\nunmeasured. No attempt should be deployed solely on these component results.\n''')
print(json.dumps({'passed':True,'standalone_fits':fits,'rtl_sha256':result['rtl_sha256']},indent=2))
